import{_ as t,o as i,c as o,a2 as s}from"./chunks/framework.CHX4lV2z.js";const k=JSON.parse('{"title":"OpenCode","description":"","frontmatter":{},"headers":[],"relativePath":"hosts/opencode.md","filePath":"hosts/opencode.md","lastUpdated":1791002220000}'),a={name:"hosts/opencode.md"};function n(l,e,r,d,p,c){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h1><p>The OpenCode integration is an <strong>in-process v1 plugin</strong> plus the shared recovery MCP server registered in OpenCode&#39;s own config. Verified on OpenCode <code>1.18.33</code>.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @lightrsi/mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> components/adapters/opencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> components/products/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> components/adapters/opencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install:opencode</span></span></code></pre></div><p>This command, in <code>~/.config/opencode</code> (or <code>$XDG_CONFIG_HOME/opencode</code>):</p><ul><li>writes a marker-tagged ESM loader at <code>plugins/tokenpilot.js</code></li><li>adds <code>mcp.tokenpilot_memory_fault_recover</code> to <code>opencode.json</code> after writing a timestamped backup. An <code>opencode.jsonc</code>-only setup is never rewritten; the snippet is printed instead.</li><li>writes <code>tokenpilot.json</code> in <code>normal</code> mode if it does not exist (never credentials)</li></ul><p>Remove with <code>npm --prefix components/adapters/opencode run uninstall:opencode</code>. It removes exactly what install added.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">TokenPilot feature</th><th style="text-align:left;">OpenCode hook</th></tr></thead><tbody><tr><td style="text-align:left;">Stable prefix</td><td style="text-align:left;"><code>experimental.chat.system.transform</code> (volatile lines moved to the tail; <code>developer</code> target only)</td></tr><tr><td style="text-align:left;">Reduction</td><td style="text-align:left;"><code>experimental.chat.messages.transform</code>, before every model step</td></tr><tr><td style="text-align:left;">Recovery</td><td style="text-align:left;">shared recovery MCP server (<code>tokenpilot_memory_fault_recover_memory_fault_recover</code> in OpenCode)</td></tr><tr><td style="text-align:left;">Eviction (opt-in)</td><td style="text-align:left;"><code>experimental.chat.messages.transform</code> + a durable per-session overlay</td></tr></tbody></table><p>OpenCode&#39;s native tool-output pruning (<code>compaction.prune</code>) is off by default in 1.18.33. TokenPilot never changes it, and <code>doctor</code> reports its current value.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ol><li>Restart OpenCode.</li><li><code>lightrsi opencode doctor</code>: loader, bundle and MCP entry present, MCP probe <code>ok</code>.</li><li>After a few turns: <code>lightrsi opencode report</code></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>OpenCode does not catch plugin errors; TokenPilot catches its own and logs to <code>~/.config/opencode/tokenpilot-state/tokenpilot/tokenpilot/adapter.log</code>.</li><li><code>opencode run --pure &quot;…&quot;</code> runs without plugins for comparison.</li></ul><p>See the <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/opencode/README.md" target="_blank" rel="noreferrer">adapter README</a> and the <a href="https://github.com/zjunlp/LightRSI/blob/main/docs/adapters/opencode-design.md" target="_blank" rel="noreferrer">design note</a>.</p>`,15)])])}const g=t(a,[["render",n]]);export{k as __pageData,g as default};
